// The Stage: the real map of Qatar from the PMTiles extract
// (docs/10_FRONTEND.md section "7. The basemap"), its style generated by
// @protomaps/basemaps in the flavour of the theme (DES-53) with the map
// tokens of section 4.1 over it, labels in the page's language drawn with
// self-hosted font faces (no glyph server), buildings flat below zoom 14 and
// extruded from zoom 14 (DES-57), and one lit layer of release units on the
// five-class ramp (section 4.3) beneath the labels (FE-46).
import {
  layers as basemapLayers,
  namedFlavor,
  type Flavor,
} from '@protomaps/basemaps';
import notoArabic400 from '@fontsource/noto-sans-arabic/files/noto-sans-arabic-arabic-400-normal.woff2?url';
import notoArabic500 from '@fontsource/noto-sans-arabic/files/noto-sans-arabic-arabic-500-normal.woff2?url';
import notoLatin400 from '@fontsource/noto-sans/files/noto-sans-latin-400-normal.woff2?url';
import notoLatin500 from '@fontsource/noto-sans/files/noto-sans-latin-500-normal.woff2?url';
import { cellToBoundary } from 'h3-js';
import {
  LngLat,
  Map,
  addProtocol,
  setWorkerUrl,
  type ExpressionSpecification,
  type LayerSpecification,
  type Map as MapLibreMap,
  type StyleSpecification,
} from 'maplibre-gl';
import workerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url';
import { Protocol } from 'pmtiles';
import {
  CLUSTER_LAYER,
  FIRM_SOURCE,
  POINT_LAYER,
  POINT_RADIUS,
  POINT_RING,
  establishmentCollection,
  establishmentLayers,
} from './establishments';
import type { Release } from './release-shape.mjs';
import { durationMs, easing, token, tokenNumber } from './tokens';

export type Theme = 'dark' | 'light';
export type Lang = 'en' | 'ar';
// A rectangle of the screen in CSS pixels.
export type Box = { left: number; top: number; right: number; bottom: number };
// The free part of the Stage, as distances in CSS pixels from each edge,
// and the plates inside it that no bright cell may sit under (ruling L-119
// item 1: the legend), and the highest zoom the City framing may take
// (ruling L-143 item 3: a city scale, at or below the unfold zoom), and the
// plates, with a margin, that no major place name may touch.
export type Free = {
  top: number;
  bottom: number;
  left: number;
  right: number;
  avoid: Box[];
  cap: number;
  plates: Box[];
};
type Point = [number, number];

// DES-60: "City" at pitch 45 and bearing minus 15; "Country" at pitch 0,
// north up, fitting the national extent with 8% padding. DES-49: pitch
// never exceeds 55 degrees.
export const CITY_PITCH = 45;
export const CITY_BEARING = -15;
const MAX_PITCH = 55;
// The national extent of Qatar's mainland and the frame of the lit layer
// (Greater Doha and Lusail), west, south, east, north.
const COUNTRY: [number, number, number, number] = [50.75, 24.47, 51.64, 26.18];
const FRAME: [number, number, number, number] = [51.33, 25.18, 51.62, 25.48];
// Ruling L-119 item 5: major places only. The basemap ranks its own places
// by the zoom from which it draws them; the page labels the localities it
// draws from zoom 9 or lower (Doha, Al Rayyan and Lusail in the frame), and
// only inside the frame of the lit layer.
export const MAJOR_PLACE_ZOOM = 9;
const FRAME_RING: Point[] = [
  [FRAME[0], FRAME[1]],
  [FRAME[2], FRAME[1]],
  [FRAME[2], FRAME[3]],
  [FRAME[0], FRAME[3]],
  [FRAME[0], FRAME[1]],
];
// The development view of the extruded buildings: Lusail at zoom 15.
const BUILDINGS_VIEW = {
  center: [51.5285, 25.3805] as Point,
  zoom: 15,
  pitch: 50,
  bearing: CITY_BEARING,
};
// DES-139: only the map canvas is capped. The cap is not yet set at slice
// S1; two device pixels per CSS pixel is this page's assumption.
export const PIXEL_RATIO_CAP = 2;
const CLASSES = [1, 2, 3, 4, 5];
const SOURCE = 'protomaps';
export const LIT_PREFIX = 'lit-';
export const LABEL_LAYERS = ['label-place'];
export const BUILDINGS_SOURCE = 'buildings';
// The home's skyline: West Bay, looking north-west over the towers.
const SKYLINE_CENTER: Point = [51.5305, 25.3225];
// The two highest classes: the bright core that no plate may cover.
const BRIGHT_STEP = 4;
// The grid of screen shifts the City framing tries, per axis.
const SHIFT_STEPS = 24;
// Round 5g, G5: how far a street camera may slide, in CSS pixels, so the
// lit cells sit in the free part the plates leave. A pitched camera does
// not move every cell by the same screen amount, so each candidate is a
// real jump and the count is read back from the projection.
const STREET_FIT_SPAN = 960;
const STREET_FIT_COARSE = 8;
const STREET_FIT_FINE = 4;
const REGULAR = 'Noto Sans Regular';
const MEDIUM = 'Noto Sans Medium';

// DES-53: points of interest, land-use colours, transit, numeric-only
// labels and every basemap label layer are left out; the page draws its own
// labels below, in the interface language only (DES-56).
const DROPPED = [
  /^landcover$/,
  /^landuse_/,
  /^roads_runway$/,
  /^roads_taxiway$/,
  /^roads_rail$/,
  /^roads_oneway$/,
  /^roads_shields$/,
  /^boundaries$/,
  /^buildings$/,
  /^pois$/,
  /^address_label$/,
  /^water_label/,
  /^water_waterway_label$/,
  /^earth_label/,
  /^roads_labels/,
  /^places_/,
];

const LATIN_RANGE = ['U+0000-024F', 'U+2000-206F', 'U+20AC'];
const ARABIC_RANGE = [
  'U+0600-06FF',
  'U+0750-077F',
  'U+FB50-FDFF',
  'U+FE70-FEFF',
];

// The map's label faces, self-hosted from the installed Noto packages: one
// name per weight, each covering Latin and Arabic (DES-56, FE-57).
export const FONT_FACES = {
  [REGULAR]: [
    { url: notoLatin400, 'unicode-range': LATIN_RANGE },
    { url: notoArabic400, 'unicode-range': ARABIC_RANGE },
  ],
  [MEDIUM]: [
    { url: notoLatin500, 'unicode-range': LATIN_RANGE },
    { url: notoArabic500, 'unicode-range': ARABIC_RANGE },
  ],
};

let configured = false;
let protocol: Protocol | null = null;

function configure(): void {
  if (configured) return;
  setWorkerUrl(workerUrl);
  protocol = new Protocol();
  addProtocol('pmtiles', protocol.tile);
  configured = true;
}

type Palette = {
  land: string;
  water: string;
  roadMinor: string;
  roadMajor: string;
  building: string;
  boundary: string;
  label1: string;
  label2: string;
  streetMajor: string;
  streetMinor: string;
  streetCasing: string;
  streetBuilding: string;
  streetEdge: string;
  ramp: string[];
};

function palette(): Palette {
  return {
    land: token('--eii-map-land'),
    water: token('--eii-map-water'),
    roadMinor: token('--eii-map-road-minor'),
    roadMajor: token('--eii-map-road-major'),
    building: token('--eii-map-building'),
    boundary: token('--eii-map-boundary'),
    label1: token('--eii-map-label-1'),
    label2: token('--eii-map-label-2'),
    streetMajor: token('--eii-map-street-major'),
    streetMinor: token('--eii-map-street-minor'),
    streetCasing: token('--eii-map-street-casing'),
    streetBuilding: token('--eii-map-street-building'),
    streetEdge: token('--eii-map-street-edge'),
    ramp: CLASSES.map((step) => token(`--eii-seq-${step}`)),
  };
}

// The flavour of the theme with every colour overridden by the map tokens:
// land-use colours and road casings take the land colour, so the map keeps
// land, water, two road classes, the coast and the buildings.
export function flavour(theme: Theme, colours: Palette): Flavor {
  const base = namedFlavor(theme);
  const land = colours.land;
  const minor = colours.roadMinor;
  const major = colours.roadMajor;
  const out: Flavor = { ...base };
  const record = out as unknown as Record<string, unknown>;
  for (const [key, value] of Object.entries(base)) {
    if (typeof value !== 'string') continue;
    if (key.includes('casing')) record[key] = land;
    else if (key.includes('highway') || key.includes('major'))
      record[key] = major;
    else if (
      key.includes('minor') ||
      key.includes('link') ||
      key.includes('other') ||
      key === 'railway' ||
      key === 'runway'
    )
      record[key] = minor;
    else if (key.includes('label')) record[key] = colours.label1;
    else record[key] = land;
  }
  out.water = colours.water;
  // Beyond the extract's edge the canvas shows the sea, not land.
  out.background = colours.water;
  out.buildings = colours.building;
  out.boundaries = colours.boundary;
  out.regular = REGULAR;
  out.bold = MEDIUM;
  out.italic = REGULAR;
  delete out.pois;
  delete out.landcover;
  return out;
}

// DES-56: labels in the interface language only; a feature with no name in
// that language is left unlabelled, never shown in the other script.
export function nameExpression(lang: Lang): ExpressionSpecification {
  if (lang === 'ar') {
    return [
      'coalesce',
      ['get', 'name:ar'],
      ['case', ['==', ['get', 'script'], 'Arabic'], ['get', 'name'], ''],
    ];
  }
  return [
    'coalesce',
    ['get', 'name:en'],
    ['case', ['has', 'script'], '', ['coalesce', ['get', 'name'], '']],
  ];
}

function labelLayers(lang: Lang, colours: Palette): LayerSpecification[] {
  const size = tokenNumber('--eii-map-label-size');
  const halo = tokenNumber('--eii-map-label-halo');
  const placeZoom = tokenNumber('--eii-map-label-zoom');
  // MapLibre places symbols from the top layer down: the streets first in
  // the stack and the major places last, so a place name wins every
  // collision with a district or a street name.
  return [
    ...roadLabels(lang, colours),
    // The clearing is drawn under the name and above the firm dots: a circle
    // does not join the labels' collisions, so a 2 px halo leaves a dot
    // showing through a letter. The clearing is land, the width of a dot
    // and its ring, and it always draws.
    districtClear(lang, colours),
    districtLabels(lang, colours),
    {
      id: 'label-place',
      type: 'symbol',
      source: SOURCE,
      'source-layer': 'places',
      minzoom: placeZoom,
      filter: [
        'all',
        ['==', ['get', 'kind'], 'locality'],
        ['<=', ['coalesce', ['get', 'min_zoom'], 99], MAJOR_PLACE_ZOOM],
        ['within', { type: 'Polygon', coordinates: [FRAME_RING] }],
      ],
      layout: {
        'symbol-sort-key': ['coalesce', ['get', 'sort_key'], 0],
        'text-field': nameExpression(lang),
        'text-font': [MEDIUM],
        'text-size': size,
        'text-letter-spacing': 0,
        'text-max-width': 8,
        'text-padding': size,
      },
      paint: {
        'text-color': colours.label1,
        'text-halo-color': colours.land,
        'text-halo-width': halo,
        'text-halo-blur': 0,
      },
    },
  ];
}

// V4 of round 5: district and quarter names from the basemap's own labels,
// from the zoom where the basemap carries them; English in capitals tracked,
// Arabic never tracked (DES-37). The layout is shared with the land-coloured
// clearing drawn just under the name.
function districtLayout(lang: Lang, clear: boolean) {
  const size = tokenNumber('--eii-map-district-size');
  return {
    'symbol-sort-key': [
      'coalesce',
      ['get', 'sort_key'],
      0,
    ] as ExpressionSpecification,
    'text-field': nameExpression(lang),
    'text-font': [MEDIUM],
    'text-size': size,
    'text-transform': (lang === 'en' ? 'uppercase' : 'none') as
      'uppercase' | 'none',
    'text-letter-spacing':
      lang === 'en' ? tokenNumber('--eii-map-district-tracking') : 0,
    'text-max-width': 8,
    'text-padding': size / 2,
    ...(clear
      ? { 'text-allow-overlap': true, 'text-ignore-placement': true }
      : {}),
  };
}

const DISTRICT_SOURCE = 'district-labels';
// The release build has already kept one point per name. A label appears
// from its own min zoom, and the layer itself from district zoom.
const DISTRICT_FILTER: ExpressionSpecification = [
  '>=',
  ['zoom'],
  ['get', 'min_zoom'],
];

function districtClear(lang: Lang, colours: Palette): LayerSpecification {
  return {
    id: 'label-district-clear',
    type: 'symbol',
    source: DISTRICT_SOURCE,
    minzoom: tokenNumber('--eii-unfold-zoom'),
    filter: DISTRICT_FILTER,
    layout: districtLayout(lang, true),
    paint: {
      'text-color': colours.land,
      'text-halo-color': colours.land,
      'text-halo-width': POINT_RADIUS + POINT_RING,
      'text-halo-blur': 0,
    },
  };
}

function districtLabels(lang: Lang, colours: Palette): LayerSpecification {
  return {
    id: 'label-district',
    type: 'symbol',
    source: DISTRICT_SOURCE,
    minzoom: tokenNumber('--eii-unfold-zoom'),
    filter: DISTRICT_FILTER,
    layout: districtLayout(lang, false),
    paint: {
      // Round 5g, finding 3: Arabic has no capitals or tracking to set a
      // district apart from a street, so it takes the tier-2 label colour
      // (DES-56); the road names keep tier 4. The halo stays the 2 px of
      // DES-56; the clearing under this layer keeps the dots out of the letters.
      'text-color': lang === 'ar' ? colours.label1 : colours.label2,
      'text-halo-color': colours.land,
      'text-halo-width': tokenNumber('--eii-map-label-halo'),
      'text-halo-blur': 0,
    },
  };
}

const MAIN_ROADS = ['motorway', 'trunk', 'primary'];
const SECONDARY_ROADS = ['secondary', 'tertiary'];

// V4 of round 5: main roads named from zoom 12, secondary streets from 14,
// every other named street from 15, each along its line.
function roadLabels(lang: Lang, colours: Palette): LayerSpecification[] {
  const size = tokenNumber('--eii-map-road-label-size');
  const detail: ExpressionSpecification = [
    'coalesce',
    ['get', 'kind_detail'],
    '',
  ];
  const tiers: [string, number, ExpressionSpecification][] = [
    [
      'label-road-main',
      12,
      [
        'any',
        ['==', ['get', 'kind'], 'highway'],
        ['in', detail, ['literal', MAIN_ROADS]],
      ],
    ],
    ['label-road-secondary', 14, ['in', detail, ['literal', SECONDARY_ROADS]]],
    [
      'label-road-street',
      15,
      [
        'all',
        ['!=', ['get', 'kind'], 'highway'],
        ['!', ['in', detail, ['literal', [...MAIN_ROADS, ...SECONDARY_ROADS]]]],
      ],
    ],
  ];
  return tiers.map(([id, minzoom, filter]) => ({
    id,
    type: 'symbol',
    source: SOURCE,
    'source-layer': 'roads',
    minzoom,
    filter: ['all', ['has', 'name'], filter],
    layout: {
      'symbol-placement': 'line',
      'text-field': nameExpression(lang),
      'text-font': [REGULAR],
      'text-size': size,
      'text-letter-spacing': 0,
      'text-padding': size / 2,
      'symbol-spacing': size * 12,
    },
    paint: {
      'text-color': colours.label2,
      'text-halo-color': colours.land,
      'text-halo-width': tokenNumber('--eii-map-label-halo'),
      'text-halo-blur': 0,
    },
  }));
}

// V5 of round 5: from street zoom the roads take a hierarchy (white roads
// on cased edges in the light theme, lifted roads in the dark), so that the
// main roads read before the streets. Below it the quiet colours stay.
export function streetRoads(
  layers: LayerSpecification[],
  colours: Palette,
): LayerSpecification[] {
  const zoom = tokenNumber('--eii-map-street-zoom');
  return layers.map((layer) => {
    if (layer.type !== 'line' || !layer.id.startsWith('roads_')) return layer;
    const paint = { ...(layer.paint ?? {}) } as Record<string, unknown>;
    const quiet = paint['line-color'];
    if (typeof quiet !== 'string') return layer;
    const id = layer.id;
    const street = id.includes('casing')
      ? colours.streetCasing
      : id.includes('highway') || id.includes('major')
        ? colours.streetMajor
        : colours.streetMinor;
    paint['line-color'] = ['step', ['zoom'], quiet, zoom, street];
    return { ...layer, paint } as LayerSpecification;
  });
}

function districtCollection(release: Release) {
  return {
    type: 'FeatureCollection' as const,
    features: release.district_labels.map((label) => ({
      type: 'Feature' as const,
      geometry: {
        type: 'Point' as const,
        coordinates: [label.lon, label.lat] as [number, number],
      },
      properties: {
        'name:en': label.en,
        'name:ar': label.ar,
        min_zoom: label.min_zoom,
      },
    })),
  };
}

function cellFeatures(release: Release) {
  return {
    type: 'FeatureCollection' as const,
    features: release.layer.cells.map(([cell, , step]) => ({
      type: 'Feature' as const,
      properties: { cls: step },
      geometry: {
        type: 'Polygon' as const,
        // h3-js returns a closed GeoJSON ring with the second argument.
        coordinates: [cellToBoundary(cell, true)],
      },
    })),
  };
}

export type StyleState = {
  theme: Theme;
  lang: Lang;
  lit: number[];
  reduced: boolean;
  // The establishment points are a data layer: off on the home (P2).
  points: boolean;
};

export type Camera = {
  center: Point;
  zoom: number;
  pitch: number;
  bearing: number;
  padding?: { top: number; bottom: number; left: number; right: number };
};

// DES-61: every class, the lowest too, is drawn at the unit opacity in both
// themes (round 5g, finding 10). Every legend swatch is its class's fill at
// the class opacity over --eii-map-land (style.css).
export function classOpacity(step: number): number {
  return tokenNumber(
    step === 1 ? '--eii-unit-opacity-1' : '--eii-unit-opacity',
  );
}

function litLayers(colours: Palette, lit: number[]): LayerSpecification[] {
  return CLASSES.map((step) => ({
    id: `${LIT_PREFIX}${step}`,
    type: 'fill',
    source: 'units',
    filter: ['==', ['get', 'cls'], step],
    paint: {
      'fill-color': colours.ramp[step - 1] ?? colours.land,
      'fill-outline-color': colours.land,
      'fill-antialias': true,
      'fill-opacity': classOpacity(step) * (lit[step - 1] ?? 0),
      'fill-opacity-transition': { duration: 0, delay: 0 },
    },
  }));
}

// V1 to V3 of round 5: with the open buildings archive, every footprint is
// drawn from zoom 13 and raised from zoom 14 by its own height (measured,
// floors times a storey, or estimated from the footprint's area; the archive
// carries the figure). Below zoom 13 the basemap's own footprints stay flat.
export function archiveLayers(colours: Palette): LayerSpecification[] {
  const zoom = tokenNumber('--eii-building-zoom');
  const opacity = tokenNumber('--eii-building-opacity');
  const street = tokenNumber('--eii-map-street-zoom');
  return [
    {
      id: 'buildings-base',
      type: 'fill',
      source: SOURCE,
      'source-layer': 'buildings',
      maxzoom: street,
      paint: { 'fill-color': colours.building, 'fill-opacity': opacity },
    },
    {
      id: 'buildings-flat',
      type: 'fill',
      source: BUILDINGS_SOURCE,
      'source-layer': 'buildings',
      minzoom: street,
      maxzoom: zoom,
      paint: {
        'fill-color': colours.streetBuilding,
        'fill-outline-color': colours.streetEdge,
        'fill-opacity': opacity,
      },
    },
    {
      id: 'buildings-3d',
      type: 'fill-extrusion',
      source: BUILDINGS_SOURCE,
      'source-layer': 'buildings',
      minzoom: zoom,
      paint: {
        'fill-extrusion-color': colours.streetBuilding,
        'fill-extrusion-opacity': opacity,
        'fill-extrusion-height': ['get', 'height'],
        'fill-extrusion-base': 0,
        'fill-extrusion-vertical-gradient': true,
      },
    },
  ];
}

function buildingLayers(colours: Palette): LayerSpecification[] {
  const zoom = tokenNumber('--eii-building-zoom');
  const opacity = tokenNumber('--eii-building-opacity');
  const fallback = tokenNumber('--eii-building-default-height');
  return [
    {
      id: 'buildings-flat',
      type: 'fill',
      source: SOURCE,
      'source-layer': 'buildings',
      maxzoom: zoom,
      paint: { 'fill-color': colours.building, 'fill-opacity': opacity },
    },
    {
      id: 'buildings-3d',
      type: 'fill-extrusion',
      source: SOURCE,
      'source-layer': 'buildings',
      minzoom: zoom,
      paint: {
        'fill-extrusion-color': colours.building,
        'fill-extrusion-opacity': opacity,
        'fill-extrusion-height': ['coalesce', ['get', 'height'], fallback],
        'fill-extrusion-base': ['coalesce', ['get', 'min_height'], 0],
      },
    },
  ];
}

export function styleFor(
  release: Release,
  state: StyleState,
  origin: string,
): StyleSpecification {
  const colours = palette();
  const transition = {
    duration: durationMs(state.reduced ? '--eii-dur-fast' : '--eii-dur-scene'),
    delay: 0,
  };
  const units = {
    type: 'geojson' as const,
    data: cellFeatures(release),
  };
  const places = release.establishments.length > 0;
  const establishmentSource = {
    type: 'geojson' as const,
    data: establishmentCollection(release.establishments),
    cluster: true,
    clusterMaxZoom: 13,
    clusterRadius: 48,
  };
  // Round 5g, findings 1, 18 and 19: the points take no ramp colour.
  const points = places
    ? establishmentLayers({
        point: token('--eii-map-point'),
        ring: token('--eii-map-point-ring'),
        visible: state.points,
      })
    : [];
  if (!release.basemap.present) {
    // Without the extract (the hosted job has none), the Stage is a neutral
    // ground with the lit layer's source and no tile.
    return {
      version: 8,
      name: 'Neutral ground',
      transition,
      ...(places ? { 'font-faces': FONT_FACES } : {}),
      sources: places
        ? { units, [FIRM_SOURCE]: establishmentSource }
        : { units },
      layers: [
        {
          id: 'background',
          type: 'background',
          paint: { 'background-color': colours.land },
        },
        ...litLayers(colours, state.lit),
        ...points,
      ],
    };
  }
  const base = streetRoads(
    basemapLayers(SOURCE, flavour(state.theme, colours)).filter(
      (layer) => !DROPPED.some((pattern) => pattern.test(layer.id)),
    ),
    colours,
  );
  const coast: LayerSpecification = {
    id: 'coast',
    type: 'line',
    source: SOURCE,
    'source-layer': 'earth',
    paint: { 'line-color': colours.boundary, 'line-width': 1 },
  };
  const archive = release.buildings.present ? release.buildings.url : null;
  const buildings =
    archive === null ? buildingLayers(colours) : archiveLayers(colours);
  const raised = buildings.filter((layer) => layer.type === 'fill-extrusion');
  const flat = buildings.filter((layer) => layer.type !== 'fill-extrusion');
  return {
    version: 8,
    name: 'Qatar',
    transition,
    'font-faces': FONT_FACES,
    light: {
      anchor: 'map',
      position: [
        1.15,
        tokenNumber('--eii-map-light-azimuth'),
        tokenNumber('--eii-map-light-polar'),
      ],
      color: token('--eii-map-light'),
      intensity: tokenNumber('--eii-map-light-intensity'),
    },
    sources: {
      [SOURCE]: {
        type: 'vector',
        url: `pmtiles://${origin}${release.basemap.url}`,
      },
      ...(archive === null
        ? {}
        : {
            [BUILDINGS_SOURCE]: {
              type: 'vector' as const,
              url: `pmtiles://${origin}${archive}`,
            },
          }),
      units,
      [DISTRICT_SOURCE]: {
        type: 'geojson' as const,
        data: districtCollection(release),
      },
      ...(places ? { [FIRM_SOURCE]: establishmentSource } : {}),
    },
    // Round 5f, F2: the establishment points go under every label, as the lit
    // cells do. A circle takes no part in the labels' collisions, so drawn
    // after them a dense cluster covered district names at street zoom.
    layers: [
      ...base,
      coast,
      ...flat,
      ...litLayers(colours, state.lit),
      ...raised,
      ...points,
      ...labelLayers(state.lang, colours),
    ],
  };
}

function idle(map: MapLibreMap): Promise<void> {
  return new Promise((resolve, reject) => {
    const fail = (event: { error?: unknown }) => {
      map.off('idle', done);
      reject(
        event.error instanceof Error ? event.error : new Error('map failed'),
      );
    };
    const done = () => {
      map.off('error', fail);
      resolve();
    };
    map.once('error', fail);
    map.once('idle', done);
  });
}

export type PlaceLabel = { name: string; kind: string; minZoom: number };
export type PlateRect = {
  name: string;
  x: number;
  y: number;
  width: number;
  height: number;
};

export type Stage = {
  map: MapLibreMap;
  units: number;
  labels: () => PlaceLabel[];
  labelsUnder: (
    rects: PlateRect[],
    layers?: string[],
  ) => { label: string; plate: string }[];
  setClass: (step: number, amount: number) => void;
  brightCorners: () => { x: number; y: number }[];
  restyle: (state: Partial<StyleState>) => void;
  country: () => void;
  frame: (free: Free, mode: 'jump' | 'ease' | 'fly') => Promise<void>;
  lightUp: (mode: 'staged' | 'instant', done: () => void) => void;
  finishLightUp: () => void;
  lighting: () => boolean;
  litLevels: () => number[];
  showBuildings: (free: () => Free) => Promise<void>;
  litUnder: (
    rects: { x: number; y: number; width: number; height: number }[],
  ) => number;
  districtNames: () => string[];
  settled: () => Promise<void>;
  rendered: () => Promise<void>;
  camera: (view: Camera) => Promise<void>;
  fitPlates: (free: () => Free) => void;
  skyline: (free: Free, mode: 'jump' | 'fly') => Promise<void>;
  setPoints: (on: boolean) => void;
  district: () => { x: number; y: number } | null;
};

export async function mountStage(
  container: HTMLElement,
  release: Release,
  initial: StyleState,
): Promise<Stage> {
  configure();
  const ratio = Math.min(window.devicePixelRatio || 1, PIXEL_RATIO_CAP);
  const state: StyleState = { ...initial, lit: [...initial.lit] };
  const origin = window.location.origin;
  const map = new Map({
    container,
    style: styleFor(release, state, origin),
    bounds: COUNTRY,
    fitBoundsOptions: { padding: 0 },
    pitch: 0,
    bearing: 0,
    maxPitch: MAX_PITCH,
    dragRotate: false,
    pitchWithRotate: false,
    touchPitch: false,
    attributionControl: false,
    maplibreLogo: false,
    fadeDuration: 0,
    pixelRatio: ratio,
    localIdeographFontFamily: false,
    canvasContextAttributes: {
      preserveDrawingBuffer: true,
      contextType: 'webgl2',
      antialias: true,
    },
  });
  await idle(map);

  const restyle = (change: Partial<StyleState>) => {
    Object.assign(state, change);
    map.setStyle(styleFor(release, state, origin), { diff: true });
  };

  const setClass = (step: number, amount: number) => {
    state.lit[step - 1] = amount;
    map.setPaintProperty(
      `${LIT_PREFIX}${step}`,
      'fill-opacity',
      classOpacity(step) * amount,
    );
  };

  let animation = 0;
  let finish: (() => void) | null = null;
  const lightUp = (mode: 'staged' | 'instant', done: () => void) => {
    cancelAnimationFrame(animation);
    if (mode === 'instant') {
      for (const step of CLASSES) setClass(step, 1);
      finish = null;
      done();
      return;
    }
    // Section 11, scene 0: the units fade in class by class from low to
    // high, one --eii-dur-base apart, each over --eii-dur-scene.
    const gap = durationMs('--eii-dur-base');
    const fade = durationMs('--eii-dur-scene');
    const ease = easing('--eii-ease-enter');
    for (const step of CLASSES) setClass(step, 0);
    const start = performance.now();
    finish = () => {
      cancelAnimationFrame(animation);
      for (const step of CLASSES) setClass(step, 1);
      finish = null;
      done();
    };
    const tick = (now: number) => {
      const elapsed = now - start;
      for (const step of CLASSES) {
        setClass(step, ease((elapsed - (step - 1) * gap) / fade));
      }
      if (elapsed >= (CLASSES.length - 1) * gap + fade) {
        finish?.();
        return;
      }
      animation = requestAnimationFrame(tick);
    };
    animation = requestAnimationFrame(tick);
  };

  // DES-60: "City" is computed. The lit units of the three highest classes (or
  // the frame of the layer, without the extract) are fitted into the free
  // part of the Stage at pitch 45 and bearing minus 15, and no corner of a
  // unit of the two highest classes may fall under a plate to avoid.
  const anchors: Point[] = [];
  const bright: Point[] = [];
  for (const [cell, , step] of release.layer.cells) {
    if (step < 3) continue;
    const ring = cellToBoundary(cell, true);
    if (ring[0] !== undefined) anchors.push([ring[0][0], ring[0][1]]);
    if (step < BRIGHT_STEP) continue;
    for (const corner of ring) bright.push([corner[0], corner[1]]);
  }
  if (anchors.length === 0) {
    anchors.push(
      [FRAME[0], FRAME[1]],
      [FRAME[2], FRAME[1]],
      [FRAME[2], FRAME[3]],
      [FRAME[0], FRAME[3]],
    );
  }
  const projected = () => {
    let left = Number.POSITIVE_INFINITY;
    let top = Number.POSITIVE_INFINITY;
    let right = Number.NEGATIVE_INFINITY;
    let bottom = Number.NEGATIVE_INFINITY;
    for (const anchor of anchors) {
      const point = map.project(anchor);
      left = Math.min(left, point.x);
      right = Math.max(right, point.x);
      top = Math.min(top, point.y);
      bottom = Math.max(bottom, point.y);
    }
    return { left, top, right, bottom };
  };
  // The search starts from the anchors' mean, so the same free part always
  // gives the same camera.
  const origin2: Point = [
    anchors.reduce((sum, anchor) => sum + anchor[0], 0) / anchors.length,
    anchors.reduce((sum, anchor) => sum + anchor[1], 0) / anchors.length,
  ];
  const under = (x: number, y: number, avoid: Box[]) =>
    avoid.some(
      (box) =>
        x >= box.left && x <= box.right && y >= box.top && y <= box.bottom,
    );
  // Ruling L-143 item 3: the major place names stay clear of every plate.
  // A name's label is the text, its halo and its padding around the point
  // of the label; each plate is grown by half that box, so that the point
  // alone can be tested. The text is measured in the page's font of the
  // screen's language, near enough to the map's own glyphs for the margin
  // of the plates to cover the difference.
  const placeAvoid = (plates: Box[]) => {
    const size = tokenNumber('--eii-map-label-size');
    const halo = tokenNumber('--eii-map-label-halo');
    const family = token(
      state.lang === 'ar' ? '--eii-font-arabic' : '--eii-font-latin',
    );
    const context = document.createElement('canvas').getContext('2d');
    if (context !== null) context.font = `500 ${size}px ${family}`;
    const out: { point: Point; avoid: Box[] }[] = [];
    for (const place of release.places) {
      const name = place[state.lang];
      if (name === '') continue;
      const width = context?.measureText(name).width ?? name.length * size;
      const across = width / 2 + size + halo;
      const down = (size * 1.2) / 2 + size + halo;
      out.push({
        point: [place.lon, place.lat],
        avoid: plates.map((box) => ({
          left: box.left - across,
          top: box.top - down,
          right: box.right + across,
          bottom: box.bottom + down,
        })),
      });
    }
    return out;
  };
  const cityTarget = (free: Free) => {
    const start = {
      center: map.getCenter(),
      zoom: map.getZoom(),
      pitch: map.getPitch(),
      bearing: map.getBearing(),
    };
    const right = window.innerWidth - free.right;
    const bottom = window.innerHeight - free.bottom;
    const names = placeAvoid(free.plates);
    // The screen points of the major places' labels, and whether each one,
    // moved by a shift, stays out from under every grown plate.
    const namePoints = () =>
      names.map((name) => ({ at: map.project(name.point), avoid: name.avoid }));
    const namesClear = (
      points: ReturnType<typeof namePoints>,
      dx: number,
      dy: number,
    ) =>
      points.every(
        (name) => !under(name.at.x + dx, name.at.y + dy, name.avoid),
      );
    const place = (center: LngLat, zoom: number) => {
      map.jumpTo({ center, zoom, pitch: CITY_PITCH, bearing: CITY_BEARING });
    };
    // The screen shift that brings the anchors' box inside the free part,
    // as near its middle as the plates to avoid allow; null when the box
    // does not fit or when no shift on a grid of SHIFT_STEPS by SHIFT_STEPS
    // keeps every bright corner out from under them and every major place
    // name clear of the plates.
    const shiftFor = (): [number, number] | null => {
      const box = projected();
      const low: Point = [free.left - box.left, free.top - box.top];
      const high: Point = [right - box.right, bottom - box.bottom];
      if (low[0] > high[0] || low[1] > high[1]) return null;
      const middle: Point = [(low[0] + high[0]) / 2, (low[1] + high[1]) / 2];
      const corners = bright.map((corner) => map.project(corner));
      const points = namePoints();
      let best: [number, number] | null = null;
      let distance = Number.POSITIVE_INFINITY;
      for (let i = 0; i <= SHIFT_STEPS; i += 1) {
        const dx = low[0] + ((high[0] - low[0]) * i) / SHIFT_STEPS;
        for (let j = 0; j <= SHIFT_STEPS; j += 1) {
          const dy = low[1] + ((high[1] - low[1]) * j) / SHIFT_STEPS;
          const away = Math.hypot(dx - middle[0], dy - middle[1]);
          if (away >= distance) continue;
          const clear =
            corners.every(
              (point) => !under(point.x + dx, point.y + dy, free.avoid),
            ) && namesClear(points, dx, dy);
          if (!clear) continue;
          best = [dx, dy];
          distance = away;
        }
      }
      return best;
    };
    const moved = (center: LngLat, shift: [number, number]) => {
      const here = map.project(center);
      return map.unproject([here.x - shift[0], here.y - shift[1]]);
    };
    // The exact test at the chosen camera: the box inside the free part
    // (half a pixel of tolerance), no bright corner under a plate and every
    // major place name clear of the plates.
    const holds = () => {
      const box = projected();
      return (
        box.left >= free.left - 0.5 &&
        box.top >= free.top - 0.5 &&
        box.right <= right + 0.5 &&
        box.bottom <= bottom + 0.5 &&
        bright.every((corner) => {
          const point = map.project(corner);
          return !under(point.x, point.y, free.avoid);
        }) &&
        namesClear(namePoints(), 0, 0)
      );
    };
    let center = new LngLat(origin2[0], origin2[1]);
    let zoom = 10;
    // Ruling L-143 item 3: the search stops at the city cap, so a lit layer
    // gathered in one district still opens on the city.
    const cap = Math.min(15, free.cap);
    for (let round = 0; round < 3; round += 1) {
      let lowZoom = 7;
      let highZoom = cap;
      for (let step = 0; step < 24; step += 1) {
        const middle = (lowZoom + highZoom) / 2;
        place(center, middle);
        if (shiftFor() === null) highZoom = middle;
        else lowZoom = middle;
      }
      zoom = lowZoom;
      place(center, zoom);
      const shift = shiftFor();
      if (shift !== null) center = moved(center, shift);
    }
    // A shift on the screen is not an exact pan under pitch: the camera
    // steps out until the exact test holds.
    place(center, zoom);
    for (let step = 0; step < 60 && !holds(); step += 1) {
      zoom -= 0.05;
      place(center, zoom);
      const shift = shiftFor();
      if (shift !== null) center = moved(center, shift);
      place(center, zoom);
    }
    map.jumpTo(start);
    return { center, zoom, pitch: CITY_PITCH, bearing: CITY_BEARING };
  };

  const settled = () =>
    new Promise<void>((resolve) => {
      if (!map.isMoving() && map.loaded()) {
        resolve();
        return;
      }
      map.once('idle', () => resolve());
    });

  // Resolves after a fresh frame with every tile loaded and every label
  // placed: the map is asked to draw once more, and its next idle event
  // follows that frame.
  const rendered = () =>
    new Promise<void>((resolve) => {
      map.once('idle', () => resolve());
      map.triggerRepaint();
    });

  const frame = async (free: Free, mode: 'jump' | 'ease' | 'fly') => {
    const target = cityTarget(free);
    if (mode === 'jump') {
      map.jumpTo(target);
      return;
    }
    const done = new Promise<void>((resolve) => {
      map.once('moveend', () => resolve());
    });
    if (mode === 'fly') {
      map.flyTo({
        ...target,
        duration: durationMs('--eii-dur-fly-long'),
        easing: easing('--eii-ease-move'),
        essential: false,
      });
    } else {
      map.easeTo({
        ...target,
        duration: durationMs('--eii-dur-fly-short'),
        easing: easing('--eii-ease-move'),
      });
    }
    await done;
  };

  const country = () => {
    const camera = map.cameraForBounds(COUNTRY, {
      padding: {
        top: window.innerHeight * 0.08,
        bottom: window.innerHeight * 0.08,
        left: window.innerWidth * 0.08,
        right: window.innerWidth * 0.08,
      },
      pitch: 0,
      bearing: 0,
    });
    if (camera !== undefined) map.jumpTo({ ...camera, pitch: 0, bearing: 0 });
  };

  // Metres in one degree of latitude, for the nearest bright unit only.
  const METRES_PER_DEGREE = 111_320;
  const nearestBrightUnit = (center: Point): Point[] => {
    let best: Point[] = [];
    let distance = Number.POSITIVE_INFINITY;
    for (const [cell, , step] of release.layer.cells) {
      if (step < BRIGHT_STEP) continue;
      const ring = cellToBoundary(cell, true);
      const corners = ring
        .slice(0, -1)
        .map((corner) => [corner[0], corner[1]] as Point);
      if (corners.length === 0) continue;
      const lon =
        corners.reduce((sum, corner) => sum + corner[0], 0) / corners.length;
      const lat =
        corners.reduce((sum, corner) => sum + corner[1], 0) / corners.length;
      const dx =
        (lon - center[0]) *
        METRES_PER_DEGREE *
        Math.cos((center[1] * Math.PI) / 180);
      const dy = (lat - center[1]) * METRES_PER_DEGREE;
      const away = dx * dx + dy * dy;
      if (away >= distance) continue;
      distance = away;
      best = corners;
    }
    return best;
  };

  // Round 5g, G3: the buildings view keeps classes 4 and 5 out from under
  // the plates, by the same shift the City framing uses, on the unit nearest
  // the Lusail camera. The zoom stays at or above the extrusion zoom.
  const showBuildings = async (readFree: () => Free) => {
    const floor = tokenNumber('--eii-building-zoom');
    const view = BUILDINGS_VIEW;
    const unit = nearestBrightUnit(view.center);
    const finite = (plates: Box[]) =>
      plates.filter(
        (box) =>
          Number.isFinite(box.left) &&
          Number.isFinite(box.top) &&
          Number.isFinite(box.right) &&
          Number.isFinite(box.bottom),
      );
    const boxOf = (points: Point[]) => {
      let left = Number.POSITIVE_INFINITY;
      let top = Number.POSITIVE_INFINITY;
      let right = Number.NEGATIVE_INFINITY;
      let bottom = Number.NEGATIVE_INFINITY;
      for (const point of points) {
        const at = map.project(point);
        left = Math.min(left, at.x);
        right = Math.max(right, at.x);
        top = Math.min(top, at.y);
        bottom = Math.max(bottom, at.y);
      }
      return { left, top, right, bottom };
    };
    const guardOf = () => {
      const bounds = map.getBounds();
      const width = map.getCanvas().clientWidth;
      const height = map.getCanvas().clientHeight;
      const out: { x: number; y: number }[] = [];
      for (const corner of bright) {
        if (!bounds.contains(corner)) continue;
        const at = map.project(corner);
        if (at.x < 0 || at.y < 0 || at.x > width || at.y > height) continue;
        out.push(at);
      }
      return out;
    };
    const shiftForUnit = (room: Free): [number, number] | null => {
      if (unit.length === 0) return [0, 0];
      const box = boxOf(unit);
      const farRight = window.innerWidth - room.right;
      const farBottom = window.innerHeight - room.bottom;
      const low: Point = [room.left - box.left, room.top - box.top];
      const high: Point = [farRight - box.right, farBottom - box.bottom];
      if (low[0] > high[0] || low[1] > high[1]) return null;
      const middle: Point = [(low[0] + high[0]) / 2, (low[1] + high[1]) / 2];
      const plates = finite(room.plates);
      const guard = guardOf();
      let best: [number, number] | null = null;
      let distance = Number.POSITIVE_INFINITY;
      for (let i = 0; i <= SHIFT_STEPS; i += 1) {
        const dx = low[0] + ((high[0] - low[0]) * i) / SHIFT_STEPS;
        for (let j = 0; j <= SHIFT_STEPS; j += 1) {
          const dy = low[1] + ((high[1] - low[1]) * j) / SHIFT_STEPS;
          const away = Math.hypot(dx - middle[0], dy - middle[1]);
          if (away >= distance) continue;
          const clear = guard.every(
            (point) => !under(point.x + dx, point.y + dy, plates),
          );
          if (!clear) continue;
          best = [dx, dy];
          distance = away;
        }
      }
      return best;
    };
    const holds = (room: Free) =>
      guardOf().every((point) => !under(point.x, point.y, finite(room.plates)));
    const steps = Math.round((view.zoom - floor) / 0.05);
    let center = new LngLat(view.center[0], view.center[1]);
    const placeAt = (zoom: number) => {
      map.jumpTo({
        center,
        zoom,
        pitch: view.pitch,
        bearing: view.bearing,
      });
    };
    for (let step = 0; step <= steps; step += 1) {
      const zoom = view.zoom - step * 0.05;
      center = new LngLat(view.center[0], view.center[1]);
      placeAt(zoom);
      let fitted = true;
      for (let round = 0; round < 3; round += 1) {
        const shift = shiftForUnit(readFree());
        if (shift === null) {
          fitted = false;
          break;
        }
        const here = map.project(center);
        center = map.unproject([here.x - shift[0], here.y - shift[1]]);
        placeAt(zoom);
      }
      if (fitted && holds(readFree())) break;
    }
    await idle(map);
  };

  // V9 of round 5: a camera set from outside (the street captures and their
  // tests); resolves after a fresh frame with every tile loaded.
  const camera = async (view: Camera) => {
    map.jumpTo(view);
    await rendered();
  };

  // P2 of round 5: the home stands over the skyline of West Bay, in the free
  // part of the Stage.
  const skyline = async (free: Free, mode: 'jump' | 'fly') => {
    const start = {
      center: map.getCenter(),
      zoom: map.getZoom(),
      pitch: map.getPitch(),
      bearing: map.getBearing(),
    };
    const target = {
      center: new LngLat(SKYLINE_CENTER[0], SKYLINE_CENTER[1]),
      zoom: tokenNumber('--eii-skyline-zoom'),
      pitch: tokenNumber('--eii-skyline-pitch'),
      bearing: CITY_BEARING,
    };
    // The skyline's centre moves to the middle of the free part.
    map.jumpTo(target);
    const middle = {
      x: (free.left + window.innerWidth - free.right) / 2,
      y: (free.top + window.innerHeight - free.bottom) / 2,
    };
    const here = map.project(target.center);
    const canvas = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
    target.center = map.unproject([
      canvas.x - (middle.x - here.x),
      canvas.y - (middle.y - here.y),
    ]);
    map.jumpTo(start);
    if (mode === 'jump') {
      map.jumpTo(target);
      return;
    }
    const done = new Promise<void>((resolve) => {
      map.once('moveend', () => resolve());
    });
    map.flyTo({
      ...target,
      duration: durationMs('--eii-dur-fly-long'),
      easing: easing('--eii-ease-move'),
      essential: false,
    });
    await done;
  };

  const setPoints = (on: boolean) => {
    state.points = on;
    for (const id of [CLUSTER_LAYER, POINT_LAYER]) {
      if (map.getLayer(id) !== undefined)
        map.setLayoutProperty(id, 'visibility', on ? 'visible' : 'none');
    }
  };

  // The screen point of the lit district's label (P1), or null.
  const district = () => {
    const place = release.district;
    if (place === null) return null;
    const point = map.project([place.lon, place.lat]);
    return { x: point.x, y: point.y };
  };

  const shownLabels = () =>
    map.getLayer(LABEL_LAYERS[0] ?? '') === undefined
      ? []
      : map.queryRenderedFeatures({ layers: LABEL_LAYERS });

  // The labels the map has placed, as it reports them: a symbol is returned
  // only when its collision box (the text and its padding) meets the query.
  const labels = (): PlaceLabel[] =>
    shownLabels().map((feature) => ({
      name: String(feature.properties.name ?? ''),
      kind: String(feature.properties.kind ?? ''),
      minZoom: Number(feature.properties.min_zoom ?? Number.NaN),
    }));

  const labelsUnder = (rects: PlateRect[], wanted = LABEL_LAYERS) => {
    const layers = wanted.filter((id) => map.getLayer(id) !== undefined);
    if (layers.length === 0) return [];
    const hits: { label: string; plate: string }[] = [];
    for (const rect of rects) {
      const found = map.queryRenderedFeatures(
        [
          [rect.x, rect.y],
          [rect.x + rect.width, rect.y + rect.height],
        ],
        { layers },
      );
      for (const feature of found) {
        hits.push({
          label: String(feature.properties.name ?? ''),
          plate: rect.name,
        });
      }
    }
    return hits;
  };

  const brightCorners = () =>
    bright.map((corner) => {
      const point = map.project(corner);
      return { x: point.x, y: point.y };
    });

  const litCentres: Point[] = release.layer.cells.map(([cell]) => {
    const ring = cellToBoundary(cell, true).slice(0, -1);
    const lon = ring.reduce((sum, corner) => sum + corner[0], 0) / ring.length;
    const lat = ring.reduce((sum, corner) => sum + corner[1], 0) / ring.length;
    return [lon, lat];
  });

  const litUnder = (
    rects: { x: number; y: number; width: number; height: number }[],
  ) => {
    let count = 0;
    for (const centre of litCentres) {
      const point = map.project(centre);
      const covered = rects.some(
        (rect) =>
          point.x >= rect.x &&
          point.x <= rect.x + rect.width &&
          point.y >= rect.y &&
          point.y <= rect.y + rect.height,
      );
      if (covered) count += 1;
    }
    return count;
  };

  // Round 5g, G5: after the plates have folded, slide the camera so the lit
  // cells fall in the free part. The slide nearest the padding the plates
  // themselves give (left inset against right inset, in the page's
  // direction) wins when several slides cover the same number.
  const fitPlates = (readFree: () => Free) => {
    const room = readFree();
    const plates = room.plates.filter(
      (box) =>
        Number.isFinite(box.left) &&
        Number.isFinite(box.top) &&
        Number.isFinite(box.right) &&
        Number.isFinite(box.bottom),
    );
    const zoom = map.getZoom();
    const pitch = map.getPitch();
    const bearing = map.getBearing();
    const origin = map.getCenter();
    const target: Point = [
      (room.left - room.right) / 2,
      (room.top - room.bottom) / 2,
    ];
    const coveredAt = (center: LngLat) => {
      map.jumpTo({ center, zoom, pitch, bearing });
      let count = 0;
      for (const place of litCentres) {
        const point = map.project(place);
        if (under(point.x, point.y, plates)) count += 1;
      }
      return count;
    };
    const choose = (span: number, steps: number, around: Point) => {
      map.jumpTo({ center: origin, zoom, pitch, bearing });
      const here = map.project(origin);
      const samples: { at: Point; center: LngLat }[] = [];
      for (let i = -steps; i <= steps; i += 1) {
        const dx = around[0] + (span * i) / steps;
        for (let j = -steps; j <= steps; j += 1) {
          const dy = around[1] + (span * j) / steps;
          samples.push({
            at: [dx, dy],
            center: map.unproject([here.x - dx, here.y - dy]),
          });
        }
      }
      let best = around;
      let covered = Number.POSITIVE_INFINITY;
      let distance = Number.POSITIVE_INFINITY;
      for (const sample of samples) {
        const count = coveredAt(sample.center);
        const away = Math.hypot(
          sample.at[0] - target[0],
          sample.at[1] - target[1],
        );
        if (count > covered || (count === covered && away >= distance))
          continue;
        covered = count;
        distance = away;
        best = sample.at;
      }
      return best;
    };
    const coarse = choose(STREET_FIT_SPAN, STREET_FIT_COARSE, [0, 0]);
    const fineSpan = STREET_FIT_SPAN / STREET_FIT_COARSE;
    const best = choose(fineSpan, STREET_FIT_FINE, coarse);
    map.jumpTo({ center: origin, zoom, pitch, bearing });
    const here = map.project(origin);
    map.jumpTo({
      center: map.unproject([here.x - best[0], here.y - best[1]]),
      zoom,
      pitch,
      bearing,
    });
  };

  const districtNames = () => {
    if (map.getLayer('label-district') === undefined) return [];
    return map
      .queryRenderedFeatures({ layers: ['label-district'] })
      .map((feature) =>
        String(
          state.lang === 'ar'
            ? feature.properties['name:ar']
            : feature.properties['name:en'],
        ),
      );
  };

  return {
    map,
    units: release.layer.cells.length,
    labels,
    labelsUnder,
    setClass,
    brightCorners,
    restyle,
    country,
    frame,
    lightUp,
    finishLightUp: () => finish?.(),
    lighting: () => finish !== null,
    litLevels: () => [...state.lit],
    showBuildings,
    litUnder,
    districtNames,
    settled,
    rendered,
    camera,
    fitPlates,
    skyline,
    setPoints,
    district,
  };
}
